// Generate src/openapi.d.ts from the server's OpenAPI document (make gen-client).
import { readFileSync, writeFileSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";

const [input, output] = process.argv.slice(2);
const schema = JSON.parse(readFileSync(input, "utf8"));
const ast = await openapiTS(schema);
const header =
  "// SPDX-License-Identifier: AGPL-3.0-or-later\n" +
  "// Generated by `make gen-client` from the server's OpenAPI document. Do not edit.\n\n";
writeFileSync(output, header + astToString(ast));
